// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"en","term":"Blockchain","aka":["distributed ledger","chain"],"short":"A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact.","body":["Each block holds a batch of transactions plus a cryptographic fingerprint (a hash) of the block before it. Because every block points back to the previous one, changing an old transaction would change its hash and break every block after it. Thousands of independent computers, called nodes, keep their own copy and reject a version that does not follow the rules.",["New blocks are added through a consensus mechanism. ",["Bitcoin","bitcoin"]," uses ",["proof of work","proof-of-work"],", where miners spend electricity to compete for the right to add the next block. ",["Ethereum","ethereum"]," and many newer networks use ",["proof of stake","proof-of-stake"],", where validators lock up coins as collateral. Either way, no single company decides which transactions are valid."],"For you as a user, the blockchain is the public record of who owns what. When you withdraw coins from an exchange, the transfer is final once it is recorded and confirmed on-chain. There is no customer service desk that can reverse it, which is why sending to the wrong address or the wrong network usually means the funds are lost."],"example":["Suppose you send 0.05 BTC from an exchange to your own wallet. The exchange broadcasts the transaction, and it waits in a queue until a miner includes it in a block, roughly every 10 minutes on Bitcoin. After that block is added, your transfer has 1 confirmation. Many exchanges wait for 2 to 6 ",["confirmations","block-confirmations"]," before crediting a Bitcoin deposit, so the money can take 20 to 60 minutes to appear, even though anyone can already see it on a ",["block explorer","block-explorer"],"."],"mistakes":["Assuming a blockchain transfer can be cancelled or refunded like a card payment once it is confirmed.","Thinking every blockchain is the same network, then sending tokens on one chain to an address on an unsupported chain.","Believing that data on a blockchain is automatically true, when it only proves what was recorded, not whether a project is honest."],"faq":[{"q":"Is a blockchain the same as Bitcoin?","a":"No. Bitcoin is one cryptocurrency that runs on its own blockchain. Ethereum, Solana and many other networks each run their own separate blockchains."},{"q":"Can a blockchain be hacked?","a":"Large public blockchains like Bitcoin and Ethereum have never had their core ledger rewritten in a normal way, because that would require controlling a huge share of mining or stake. Most losses come from hacked exchanges, buggy smart contracts or stolen private keys, not from the chain itself."},{"q":"Who controls a public blockchain?","a":"No single party. The rules are enforced by the software that thousands of independent nodes run, and changes need broad agreement from developers, node operators and miners or validators."}],"title":"What is a blockchain? Meaning and how it works","description":"Learn what a blockchain is, how blocks and confirmations work, and why on-chain transfers cannot be reversed.","related":[["cryptocurrency","Cryptocurrency","A cryptocurrency is a digital asset that is issued and transferred on a blockchain, secured by cryptography instead of a bank or central authority."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["block-explorer","Block explorer","A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"en","term":"Trading volume","aka":["volume","24h volume"],"short":"Trading volume is the total amount of an asset traded over a set period, usually shown as the 24-hour volume in coins or in USD value.","body":[["Every time a buyer and a seller match, the trade adds to volume. Exchanges and data sites usually display 24-hour volume, and charts show volume per candle as bars under the price. Volume can be counted in the base coin (for example 5,000 ",["BTC","bitcoin"],") or in quote value (for example 300 million ",["USDT","usdt"],")."],["Traders read volume as a measure of participation. A price breakout on rising volume suggests many traders agree with the move. A move on very low volume is easier to reverse. Volume also hints at ",["liquidity","liquidity"],", although depth in the ",["order book","order-book"]," is a more direct measure."],["Volume figures need care. Spot and derivatives volume are often reported separately, and derivatives volume is usually far larger because it counts leveraged notional value. Some venues and tokens have inflated numbers due to ",["wash trading","wash-trading"],", so compare volume across several sources and check it against order book depth."]],"example":"Suppose a token shows 40 million USDT of 24-hour volume on an exchange, but the order book only holds 30,000 USDT of orders within 2% of the price. Real traders would need over 1,000 full turnovers of that depth in a day to produce such volume. That mismatch is a warning sign. By contrast, a pair with 40 million USDT of volume and 2 million USDT of depth within 2% looks far more consistent.","mistakes":["Treating high 24-hour volume as proof that a market is liquid or trustworthy.","Comparing spot volume on one site with derivatives volume on another.","Reading a single volume spike as a buy or sell signal without looking at price direction."],"faq":[{"q":"Is high trading volume good?","a":"It usually means more participation and easier execution, but not always. Volume can be inflated, and high volume during a sell-off reflects heavy selling, not strength."},{"q":"What is the difference between volume and market cap?","a":"Market cap is the value of all coins in circulation at the current price. Volume is how much of the coin changed hands over a period."}],"title":"What is trading volume in crypto? Meaning explained","description":"Learn what crypto trading volume measures, how to read volume bars on a chart and why some volume numbers can be misleading.","related":[["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."],["open-interest","Open interest","Open interest is the total number or value of derivatives contracts, such as futures or options, that are currently open and not yet closed or settled."],["wash-trading","Wash trading","Wash trading is when the same person or group buys and sells an asset to themselves to create fake trading volume and a false impression of demand."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"en","term":"Position sizing","aka":["position size","trade sizing"],"short":"Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account.","body":["Good position sizing starts with risk, not with how confident you feel. Many traders limit each trade to losing 1% or 2% of their account. You then work backwards: the distance between your entry and stop-loss tells you how large the position can be.",["The basic formula is position size = amount you are willing to lose ÷ distance to stop-loss. A wide stop means a smaller position, and a tight stop allows a larger one. ",["Leverage","leverage"]," changes how much margin you need to open the position, but it does not change how much you lose when the stop is hit."],["Sizing also protects you from a losing streak. If you risk 20% per trade, five losses in a row can wipe out most of your account. At 1% per trade, the same streak costs about 5% and you can keep trading. With leveraged products, also check that your ",["liquidation price","liquidation-price"]," sits well beyond your stop-loss."]],"example":["Suppose your account holds 5,000 ",["USDT","usdt"]," and you risk 1%, which is 50 USDT. You want to buy ",["ETH","ethereum"]," at 2,500 USDT with a stop-loss at 2,400, a 100 USDT distance. Position size = 50 ÷ 100 = 0.5 ETH, worth 1,250 USDT. If the stop triggers, you lose 0.5 × 100 = 50 USDT plus fees. Using 5x leverage, you would ",["post only","post-only-order"]," 250 USDT of margin, but the loss at the stop would still be 50 USDT."],"mistakes":["Choosing position size by leverage or by feel instead of by the stop-loss distance.","Forgetting to include fees and slippage in the planned loss.","Increasing size after a few wins or losses, which turns a plan into a gamble."],"faq":[{"q":"How much should I risk per trade?","a":"Many traders use 1% to 2% of their account per trade. The right number depends on your strategy and tolerance, but small fixed risk makes losing streaks survivable."},{"q":"Does leverage increase my position size?","a":"Leverage lets you open a bigger position with less margin. Your profit and loss still depend on the full position size, so size first and pick leverage second."}],"title":"What is position sizing? How much to risk per trade","description":"Learn how to calculate position size from your account risk and stop-loss distance, with a clear crypto trading example.","related":[["risk-reward-ratio","Risk-reward ratio","The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide how much you could lose before you decide how much to buy"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"en","term":"Funding rate","aka":["funding fee","funding"],"short":"A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price.","body":[[["Perpetual futures","perpetual-futures"]," never expire, so the exchange needs a mechanism that pulls their price toward the ",["index price","index-price"]," of the ",["spot market","spot-trading"],". At each funding time, if the rate is positive, traders holding longs pay those holding shorts. If it is negative, shorts pay longs. The payment goes between traders, not to the exchange."],"The rate is usually built from two parts: a premium component that measures how far the perp trades from the index, and an interest component. Exchanges publish the predicted rate and a countdown to the next settlement. Funding is commonly settled every 8 hours, but some exchanges and pairs use 1, 2 or 4 hours, and rates may be capped.",["Funding is calculated on your position value, not on your margin, so ",["leverage","leverage"]," makes it matter more. You only pay or receive funding if you hold a position at the settlement moment. Persistently high positive funding shows that many traders are leveraged long, which can make the market vulnerable to sharp drops when they unwind."]],"example":["Suppose you hold a 30,000 ",["USDT","usdt"]," short on a SOL perpetual with 3,000 USDT of margin. The funding rate is +0.03% every 8 hours, so as a short you receive 30,000 × 0.03% = 9 USDT per interval, or 27 USDT a day. A trader holding the opposite 30,000 USDT long pays that same 27 USDT a day, which is almost 1% of a 3,000 USDT margin every day."],"mistakes":["Calculating funding on margin instead of the full position value.","Assuming funding is always settled every 8 hours on every exchange and pair.","Reading high positive funding as a guaranteed signal that price will fall."],"faq":[{"q":"Is a negative funding rate bullish?","a":"It shows that shorts are dominant and paying longs, which can fuel a short squeeze. It is a sentiment indicator, not a reliable price signal on its own."},{"q":"Do I pay funding if I close before the funding time?","a":"No. Funding applies only to positions open at the exact settlement time on your exchange."}],"title":"What is a funding rate? Meaning in crypto futures","description":"Learn what a funding rate is, who pays whom, how often it settles and how to calculate its cost on a perpetual position.","related":[["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["funding-rate-arbitrage","Funding rate arbitrage","Funding rate arbitrage is a market-neutral strategy that collects funding payments by holding opposite positions, usually spot long and perpetual short, so price moves largely cancel out."],["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price."],["index-price","Index price","The index price is a reference price for an asset calculated from a weighted average of spot prices on several major exchanges, used to anchor futures pricing."],["open-interest","Open interest","Open interest is the total number or value of derivatives contracts, such as futures or options, that are currently open and not yet closed or settled."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Price flat, balance down? Finish the last level with costs in mind"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"en","term":"DeFi (decentralized finance)","aka":["decentralized finance","DeFi protocols"],"short":"DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges.","body":[["In DeFi, the rules are written into smart contracts that anyone can use from a ",["self-custody wallet","non-custodial-wallet"],". You do not open an account or hand over your coins to a company. Well-known examples include Uniswap for swapping tokens, Aave for lending and borrowing, and Lido for ",["liquid staking","liquid-staking"],"."],"Because the contracts are public, DeFi apps can be combined like building blocks: a token you receive from one protocol can be deposited in another. This is often called composability. It enables new products quickly, but it also means a failure in one protocol can spread to others.",["The main risks are different from those of a ",["centralized exchange","centralized-exchange"],": ",["smart contract","smart-contract"]," bugs, manipulated price oracles, malicious token approvals, depegs of ",["stablecoins","stablecoin"]," or ",["staking","staking"]," tokens, and your own mistakes, which nobody can reverse."]],"example":"Suppose you hold 2 ETH. On a lending protocol, you deposit them as collateral, worth 6,000 USDC at an illustrative price of 3,000 USDC per ETH, and borrow 2,000 USDC. You swap 1,000 USDC on a DEX for another token and keep 1,000 USDC in your wallet. Every step happens through contracts you sign from your wallet. If ETH fell to about 1,250 USDC, depending on the protocol's settings, your collateral could be liquidated to repay the loan.","mistakes":["Treating a high yield as free money without asking where the yield comes from.","Using a new protocol with a large amount before it has any track record or audit history.","Forgetting that every transaction costs gas and that failed transactions still pay fees."],"faq":[{"q":"Is DeFi safe?","a":"DeFi removes the need to trust an exchange, but adds smart contract, oracle and user-error risk. Safety depends on the protocol's code, history and how carefully you use it."},{"q":"Do I need KYC to use DeFi?","a":"Most DeFi protocols do not require identity checks to interact with the contracts, though some front-end websites restrict access by country."}],"title":"What is DeFi? Decentralized finance explained","description":"Learn what DeFi is, how smart contracts replace banks and exchanges, and the main risks to understand before you use it.","related":[["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["total-value-locked","Total value locked (TVL)","Total value locked (TVL) is the total market value of crypto deposited in a DeFi protocol or blockchain's smart contracts, used as a rough measure of its size and usage."],["defi-lending","DeFi lending","DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow."],["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"en","term":"Cross-chain bridge","aka":["crypto bridge","blockchain bridge","bridge"],"short":"A cross-chain bridge is a protocol that moves tokens or messages between two blockchains, usually by locking or burning assets on one chain and releasing or minting matching assets on the other.","body":[["Blockchains cannot read each other directly. A bridge connects them. In a lock-and-mint design, you lock tokens in a ",["contract","smart-contract"]," on chain A, and the bridge mints a wrapped version on chain B. Other designs use ",["liquidity","liquidity"]," pools on both sides, or burn the token on one chain and mint it natively on the other, as Circle's CCTP does for ",["USDC","usdc"],"."],"Bridges hold large amounts of locked assets, and they rely on validators, multisigs or other mechanisms to confirm what happened on the other chain. That makes them a frequent target: several of the largest crypto hacks were bridge exploits.",["Before bridging, check that the bridge is the official or widely used one for that route, that the token you will receive is the version accepted on the destination chain, and what fees and wait times apply. Moving funds through a ",["centralized exchange","centralized-exchange"]," is sometimes simpler and cheaper."]],"example":["Suppose you want to move 2,000 USDC from ",["Ethereum","ethereum"]," to Arbitrum. A bridge quotes a fee of 3 USDC plus Ethereum gas of a few dollars and an arrival time of about 15 minutes. You approve the bridge contract, send the transfer and receive 1,997 USDC on Arbitrum. Alternatively, you could deposit to an exchange on Ethereum and withdraw on Arbitrum if the exchange supports both networks."],"mistakes":["Using a bridge link from a social media reply instead of the official site.","Receiving a wrapped token version on the destination chain that local apps do not accept.","Bridging a large amount without first sending a small test."],"faq":[{"q":"Are cross-chain bridges safe?","a":"They carry extra risk because they hold large locked balances and depend on their security design. Many users limit the amount they keep in bridged tokens."},{"q":"How long does bridging take?","a":"From a minute to several days, depending on the bridge design and the chains. Some official rollup bridges take about a week to withdraw back to Ethereum."}],"title":"What is a cross-chain bridge? How bridges work","description":"Learn how cross-chain bridges move tokens between blockchains, why they are frequent hack targets, and what to check first.","related":[["wrapped-token","Wrapped token","A wrapped token is a token on one blockchain that represents another asset one-to-one, such as WBTC representing bitcoin on Ethereum, backed by the original asset held by a custodian or smart contract."],["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security."],["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"en","term":"Stablecoin","aka":["stable coin","stablecoins"],"short":"A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms.","body":[["Stablecoins let traders hold dollar value on-chain and move it quickly between exchanges and wallets. Most trading pairs on crypto exchanges are quoted in stablecoins such as ",["USDT","usdt"]," and ",["USDC","usdc"],"."],"There are several types. Fiat-backed stablecoins, like USDT from Tether and USDC from Circle, hold reserves and let approved customers redeem them. Crypto-backed stablecoins, like DAI or USDS, are overcollateralized by crypto in smart contracts. Synthetic dollars, like Ethena's USDe, use hedged positions. Algorithmic designs without solid collateral have failed in the past, most famously TerraUSD in 2022.",["Stablecoins are stable, not risk-free. Risks include reserve quality, the issuer freezing addresses, regulatory changes and depegs, when the price drifts away from 1 dollar. Rules also differ by region; in the EU, ",["MiCA","mica"]," stablecoin rules have applied since 30 June 2024."]],"example":["Suppose you sell 0.1 ",["BTC","bitcoin"]," at 60,000 USDT on an exchange and receive 6,000 USDT. A week later BTC falls to 54,000. Your 6,000 USDT is still worth about 6,000 dollars, while 0.1 BTC would now be worth 5,400. If the stablecoin itself dipped to 0.97 dollars during a ",["depeg","depeg"],", your 6,000 USDT would be worth about 5,820 dollars until it recovered."],"mistakes":["Treating all stablecoins as equally safe regardless of how they are backed.","Sending a stablecoin over a network that the receiving platform does not support.","Holding a little-known stablecoin because it offers a much higher yield than the main ones."],"faq":[{"q":"Are stablecoins the same as dollars?","a":"No. They are tokens designed to track the dollar. Their value depends on the issuer's reserves, redemption and the market."},{"q":"What is the most used stablecoin?","a":"USDT, issued by Tether, has long been the largest stablecoin by market capitalization, with USDC from Circle second."},{"q":"Can a stablecoin lose its peg?","a":"Yes. Even major stablecoins have traded below 1 dollar briefly during stress, and some smaller ones never recovered."}],"title":"What is a stablecoin? Types and risks explained","description":"What a stablecoin is, how fiat-backed, crypto-backed and synthetic stablecoins differ, and the risks behind a stable price.","related":[["usdt","USDT (Tether)","USDT, also called Tether, is the largest US dollar stablecoin, issued by Tether, designed to stay at 1 dollar and backed by reserves the company reports in regular attestations."],["usdc","USDC","USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations."],["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD."],["crypto-backed-stablecoin","Crypto-backed stablecoin","A crypto-backed stablecoin is a stablecoin issued against crypto collateral locked in smart contracts, usually worth more than the coins created, so the token can stay near 1 USD."],["synthetic-dollar","Synthetic dollar (delta-neutral stablecoin)","A synthetic dollar is a dollar-pegged token backed by a crypto asset plus an equal short futures position, so price moves cancel out and the combined value stays near 1 USD."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Is USDT a dollar? Why is it everywhere when you buy crypto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
